package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTeDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("అన్ని హానుల నుండి రక్షణ", "అల్లాహ్ పేరిట, ఆయన పేరిట భూమిపై లేదా ఆకాశాలలో ఏదీ హాని చేయదు, మరియు ఆయన అన్నీ వినేవాడు, అన్నీ తెలిసినవాడు.", "ప్రతి ఉదయం మరియు సాయంత్రం మూడు సార్లు.", "ఉదయం, సాయంత్రం మూడు సార్లు ఎవరైనా ఇలా చెబితే, అతనికి ఏ హాని జరగదు."),
        "dua_raditu_billahi" to DuaText("అల్లాహ్ పట్ల సంతృప్తి", "అల్లాహ్ నా ప్రభువుగా, ఇస్లాం నా మతంగా, ముహమ్మద్ సల్లల్లాహు అలైహి వసల్లం నా ప్రవక్తగా నేను సంతోషిస్తున్నాను.", "మూడు సార్లు ఉదయం మరియు సాయంత్రం.", "తీర్పు రోజున ఆయనను సంతోషపెట్టడం అల్లాహ్కు హక్కు అవుతుంది."),
        "dua_hasbiyallah" to DuaText("హస్బియల్లా (అల్లాహ్ చాలు)", "నాకు అల్లాహ్ చాలు, ఆయన తప్ప మరో దేవుడు లేడు. నేను ఆయనపైనే ఆధారపడతాను, ఆయనే పరాక్రమశాలి సింహాసనానికి ప్రభువు.", "ఉదయం మరియు సాయంత్రం ఏడు సార్లు.", "ఖురాన్ లోని ఒక పద్యం-ఈ లోకానికి మరియు పరలోకానికి సంబంధించిన ఆందోళనలకు అల్లాహ్ సరిపోతున్నాడు."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("సుభాన్ అల్లాహి వా బిహమ్దిహి", "అల్లాహ్ మహిమగలవాడు మరియు అన్ని ప్రశంసలు ఆయనవే.", "రోజుకు వంద సార్లు.", "రోజుకు వంద సార్లు చెప్పేవాడు తన పాపాలు సముద్రపు నురుగు లాగా ఉన్నప్పటికీ క్షమింపబడతాయి."),
        "dua_tahleel_100" to DuaText("లా ఇలాహా ఇల్లల్లాహు వాహ్దాహు", "అల్లాహ్ తప్ప ఎవరూ ఆరాధించబడటానికి హక్కు లేదు, ఒంటరిగా, భాగస్వామి లేకుండా. ఆధిపత్యం మరియు ప్రశంసలు అతనివే, మరియు అతను అన్ని విషయాలపై అధికారం కలిగి ఉన్నాడు.", "రోజుకు వంద సార్లు చెప్పడం గొప్ప ధర్మం.", "పది మంది బానిసలను విడిపించిన ప్రతిఫలం, వంద మంచి పనులు వ్రాసిన ప్రతిఫలం, వంద పాపాలు చెరిపివేయబడ్డాయి, సాయంత్రం వరకు సైతాన్ నుండి రక్షణ లభించింది."),
        "dua_leaving_mosque" to DuaText("మసీదు నుండి బయలుదేరడం", "ఓ అల్లాహ్, నేను నీ అనుగ్రహం గురించి అడుగుతున్నాను.", "ఎడమ పాదంతో మసీదు నుండి బయటకు అడుగుపెట్టినప్పుడు.", "మసీదు నుండి బయటకు వెళ్ళేటప్పుడు అల్లాహ్ అనుగ్రహం మరియు ఏర్పాటు కోసం అడగడం."),
        "dua_after_adhan" to DuaText("అదాన్ తరువాత", "ఓ అల్లాహ్, ఈ పరిపూర్ణమైన పిలుపు మరియు స్థాపించబోయే ప్రార్థనకు ప్రభువు, ముహమ్మద్ సల్లల్లాహు అలైహి వసిలా మరియు ధర్మాన్ని ప్రసాదించండి మరియు మీరు అతనికి వాగ్దానం చేసిన ప్రశంసించబడిన స్థానానికి అతన్ని పెంచండి.", "ఆధాన్ పూర్తయిన తర్వాత.", "ఇలా చెప్పే వారెవరైనా తీర్పు రోజున ప్రవక్త సలీం సలీం మధ్యవర్తిత్వం చేయబడతారు."),
        "dua_after_salah_istighfar" to DuaText("ఫర్ద్ సలాహ్ తర్వాత", "నేను అల్లాహ్ క్షమాపణను (3 సార్లు) కోరుతున్నాను. ఓ అల్లాహ్, నీవు సలాం లాగా ఉన్నావు మరియు నీ నుండి శాంతి ఉంది. ఓ మహిమ మరియు గౌరవం కలిగినవాడే, నీవు ధన్యుడవు.", "సలాం తర్వాత వెంటనే.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ప్రతి తప్పనిసరి ప్రార్థన తర్వాత దీనిని పఠించారు."),
        "dua_after_salah_help_dhikr" to DuaText("నిన్ను గుర్తుంచుకోవడానికి నాకు సహాయం చేయండి", "ఓ అల్లాహ్, నిన్ను జ్ఞాపకం చేసుకోవడానికి, నీకు కృతజ్ఞతలు చెప్పడానికి మరియు నిన్ను ఉత్తమ మార్గంలో ఆరాధించడానికి నాకు సహాయం చేయండి.", "ప్రతి ప్రార్థన తరువాత-ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ము'ద్ (ర) కు అలా చెప్పమని సలహా ఇచ్చారు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం యొక్క ప్రత్యేక సలహా-ఆరాధనలో శ్రేష్ఠత మరియు స్థిరత్వం."),
        "dua_sleep_tasbeeh" to DuaText("నిద్రపోయే ముందు తస్బెహ్-ఎ-ఫాతిమా", "మహిమగల అల్లాహ్ (33), అన్ని ప్రశంసలు అల్లాహ్ (33), అల్లాహ్ గొప్పవాడు (34).", "నిద్రపోయే ముందు-ప్రవక్త సల్లల్లాహు అలైహి వసల్లం దీనిని ఫాతిమా మరియు అలీ (ర) లకు నేర్పించారు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఒక సేవకుడి కంటే మీకు మంచిదని చెప్పారు."),
        "dua_sleep_qina_adhab" to DuaText("శిక్ష నుండి రక్షణ", "ఓ అల్లాహ్, నీవు నీ సేవకులను పునరుత్థానం చేసిన రోజున నీ శిక్ష నుండి నన్ను రక్షించు.", "మూడు సార్లు, కుడి చేతిని చెంప కింద ఉంచండి.", "నిద్రను మరణానికి గుర్తుగా మరియు పరలోకానికి సిద్ధంగా మారుస్తుంది."),
        "dua_bad_dream" to DuaText("ఒక చెడు కల తరువాత", "నేను శపించబడిన షైతాన్ నుండి అల్లాహ్ ఆశ్రయాన్ని కోరుతున్నాను.", "ఒక చెడు కల తరువాతః మూడు సార్లు ఎడమ వైపుకు తేలికగా ఉమ్మివేయండి, ఆపై మరొక వైపు తిరగండి.", "చెడు కల మీకు హాని చేయదు; దాని గురించి ఎవరికీ చెప్పకండి."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("యా హయ్యూ యా కయ్యూమ్", "ఓ నిత్యజీవులారా, అందరి సంరక్షకుడా! నీ దయతో నేను సహాయం కోరుతున్నాను.", "ఒక విషయం చాలా భారంగా మారినప్పుడు.", "ప్రవక్తను ఏదైనా బాధపెట్టినప్పుడల్లా ఆయన ఇలా చెప్పేవారు."),
        "dua_entering_market" to DuaText("మార్కెట్ లోకి ప్రవేశం", "అల్లాహ్ తప్ప, ఒంటరిగా, భాగస్వామి లేకుండా ఆరాధించబడే హక్కు ఎవరికీ లేదు. ఆధిపత్యం మరియు ప్రశంసలు ఆయనకునే. అతను జీవం ఇస్తాడు మరియు మరణాన్ని కలిగిస్తాడు, మరియు అతను నిత్యజీవుడు మరియు ఎప్పటికీ మరణించడు. అతని చేతిలో అంతా మంచిది, మరియు అతను అన్నింటిపై అధికారం కలిగి ఉన్నాడు.", "మార్కెట్లోకి ప్రవేశించినప్పుడు.", "హదీసులో దానికి గొప్ప బహుమతి (ఒక మిలియన్ మంచి పనులు) గురించి ప్రస్తావించబడింది."),
        "dua_adam_forgiveness" to DuaText("ప్రవక్త ఆదమ్ (అ. స.) యొక్క దువా", "మా ప్రభూ, మేము మాకు అన్యాయము చేసుకున్నాము, మరియు మీరు మమ్మల్ని క్షమించకపోతే మరియు మమ్మల్ని కరుణించకపోతే, మేము నష్టపోయేవారిలో ఉంటాము.", "ఆదాము మరియు హవా (AS) యొక్క పశ్చాత్తాపం యొక్క దుఆ.", "మానవజాతి యొక్క మొదటి పశ్చాత్తాపం-అల్లాహ్ దానిని అంగీకరించాడు."),
        "dua_abu_bakr" to DuaText("దుఆ అబూ బకర్ (ర) కు బోధించాడు.", "ఓ అల్లాహ్, నాకు నేను చాలా అన్యాయం చేశాను, నీవు తప్ప మరెవరూ పాపాలను క్షమించరు, కాబట్టి నీ నుండి నాకు క్షమాపణ ఇవ్వండి, నన్ను కరుణించండి. నిశ్చయంగా, నీవు క్షమాపణ ఇచ్చేవాడవు, కరుణామయుడవు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం అబూ బకర్ అస్-సిద్దిక్ (ర) కు ప్రార్థనలో (తాషాహూద్ తరువాత) చెప్పడం నేర్పించారు.", "ప్రార్థన ముగింపు కోసం సున్నహ్ దుఆ."),
        "dua_astaghfirullah_atubu" to DuaText("రోజువారీ ఇస్తిఘఫర్", "నేను అల్లాహ్ క్షమాపణ కోరుతున్నాను మరియు పశ్చాత్తాపంతో ఆయన వైపు మొగ్గు చూపుతున్నాను.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం రోజుకు డెబ్బై సార్లు కంటే ఎక్కువ క్షమాపణలు కోరారు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఇలా అన్నారుః నేను అల్లాహ్ క్షమాపణ కోరుతున్నాను మరియు రోజుకు డెబ్బై సార్లు కంటే ఎక్కువ పశ్చాత్తాపపడుతున్నాను."),
        "dua_laylatul_qadr" to DuaText("లైలత్ అల్-ఖాదర్ కోసం దువా", "ఓ అల్లాహ్, నీవు చాలా క్షమించేవాడవు మరియు క్షమించడానికి ఇష్టపడతావు, కాబట్టి నన్ను క్షమించు.", "లైలత్ అల్-ఖాదర్ కోసం ఆయిషా (ఆర్ఏ) కు నేర్పించారు.", "రంజాన్ చివరి రాత్రులు మరియు లైలత్ అల్-ఖాదర్ కోసం ప్రత్యేక దుఆ."),
        "dua_family_coolness" to DuaText("కంటి చల్లదనం (జీవిత భాగస్వామి & పిల్లలు)", "మా ప్రభూ, మా జీవిత భాగస్వాముల నుండి మరియు మా సంతానం నుండి మా కళ్ళ చల్లదనాన్ని మాకు ప్రసాదించండి, మరియు మమ్మల్ని నీతిమంతులకు నాయకులుగా చేయండి.", "నీతిమంతుడైన జీవిత భాగస్వామి మరియు పిల్లల కోసం ఖురాన్ దుఆ.", "ఇంట్లో శాంతి మరియు నీతిమంతులైన పిల్లల కోసం."),
        "dua_righteous_children" to DuaText("నీతిమంతుడైన సంతానం కోసం", "నా ప్రభూ, నీ నుండి నాకు స్వచ్ఛమైన సంతానాన్ని ప్రసాదించు. నిశ్చయంగా నీవు ప్రార్థన వినేవాడవు.", "ప్రవక్త జకారియా (అ. స.) యొక్క దుఆ.", "పిల్లలు కోరుకునే వారికి ఖురాన్ దుఆ."),
        "dua_ibrahim_prayer_family" to DuaText("ప్రార్థన స్థాపకులు", "నా ప్రభూ, నన్ను ప్రార్థనను, నా సంతానం నుండి ప్రార్థనను స్థాపించే వ్యక్తిగా చేయండి. మా ప్రభూ! నా ప్రార్థనను అంగీకరించండి. మా ప్రభూ! లెక్క నిర్ణయించబడిన రోజున నన్ను, నా తల్లిదండ్రులను, విశ్వాసులను క్షమించండి.", "ప్రవక్త ఇబ్రహీం (అ. స.) తన కోసం, తన వారసుల కోసం చేసిన దుఆ.", "సాధారణంగా ప్రార్థన చివరిలో పఠిస్తారు."),
        "dua_newlywed" to DuaText("నవ దంపతులకు అభినందనలు", "అల్లాహ్ మిమ్మల్ని ఆశీర్వదించి, మీపై ఆశీర్వాదాలు పంపించి, మీ ఇద్దరినీ మంచితనంతో కలిసి తీసుకురావాలి.", "ఎవరికైనా వారి వివాహానికి అభినందనలు తెలియజేసేటప్పుడు.", "వివాహానికి సున్నహ్ అభినందనలు."),
        "dua_before_eating" to DuaText("తినడానికి ముందు", "అల్లాహ్ పేరిట. (మర్చిపోతేః) అల్లాహ్ పేరిట, దాని ప్రారంభంలో మరియు చివరిలో.", "తినడానికి ముందు. మీరు మర్చిపోతే, పాక్షికంగా చెప్పండి.", "బిస్మిల్లా అని చెప్పడం వల్ల సైతాన్ ఆహారాన్ని పంచుకోకుండా ఉంచుతుంది."),
        "dua_after_eating" to DuaText("భోజనం చేసిన తర్వాత", "నాకు ఈ ఆహారం ఇచ్చి, నా వంతు నుండి ఎటువంటి శక్తి లేదా శక్తి లేకుండా నాకు అందించిన అల్లాహ్ కోసం అన్ని ప్రశంసలు.", "భోజనం పూర్తి చేసిన తరువాత.", "క్షమించబడ్డారని చెప్పే వ్యక్తి యొక్క గత పాపాలు."),
        "dua_host" to DuaText("అతిధేయుడి కోసం", "ఓ అల్లాహ్, నీవు వారికి అందించిన దానిలో వారిని ఆశీర్వదించు, వారిని క్షమించి, వారిని కరుణించండి.", "అతిధేయుడి కోసం, ఒకరి ఇంట్లో భోజనం చేసిన తర్వాత.", "సున్నా మార్గంలో అతిధేయుడికి కృతజ్ఞతలు."),
        "dua_breaking_fast" to DuaText("ఉపవాసం విచ్ఛిన్నం చేసిన తరువాత", "దాహం పోయింది, సిరలు తడిసివేయబడ్డాయి, మరియు అల్లాహ్ కోరుకుంటే, ప్రతిఫలం నిర్ధారించబడుతుంది.", "ఇఫ్తార్ సమయంలో.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఉపవాసం విరమించుకునేటప్పుడు ఈ విషయం చెప్పారు."),
        "dua_new_clothes" to DuaText("కొత్త దుస్తులు ధరించడం", "ఓ అల్లాహ్, సమస్త స్తుతులు నీవే. నీవు నాకు ఈ దుస్తులు ధరించావు. దాని మంచితనం, దాని వల్ల కలిగే మంచితనం గురించి నేను నిన్ను అడుగుతున్నాను. దాని చెడు, దాని వల్ల కలిగే చెడు నుండి నేను నిన్ను ఆశ్రయిస్తున్నాను.", "కొత్త దుస్తులు ధరించినప్పుడు (చొక్కా లేదా తలపాగా వంటి వాటికి పేరు పెట్టడం).", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం కొత్త దుస్తులు ధరించినప్పుడు ఈ దుఆ చేశారు. (దుస్తులు ధరించడానికి రోజువారీ దుఆ'దుస్తులు ధరించడం'కింద ఉంటుంది)"),
        "dua_rabbana_atina" to DuaText("ఈ లోకంలో మరియు పరలోకంలో మంచిది", "మా ప్రభూ, మాకు ఈ లోకంలో మంచిని, పరలోకంలో మంచిని ప్రసాదించండి, అగ్ని శిక్ష నుండి మమ్మల్ని రక్షించండి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం చాలా తరచుగా చేసే దుఆ.", "ఈ లోకంలోని మరియు పరలోకంలోని ప్రతి మంచిని సేకరించే దుఆ."),
        "dua_rabbi_zidni_ilma" to DuaText("జ్ఞానంలో పెరుగుదల", "నా ప్రభూ, నాకు జ్ఞానాన్ని పెంచండి.", "జ్ఞానాన్ని పెంచడానికి.", "అల్లాహ్ ప్రవక్త (సల్లల్లాహు అలైహి వసల్లం) ను జ్ఞానం తప్ప మరేమీ పెంచవద్దని ఆదేశించాడు."),
        "dua_musa_sharh_sadr" to DuaText("ఛాతీ తెరవడం (మూసా AS)", "నా ప్రభూ, నా కోసం నా ఛాతీని విస్తరించండి, నా కోసం నా పనిని సులభతరం చేయండి, నా నాలుక నుండి ముడి విప్పండి, తద్వారా వారు నా మాటను అర్థం చేసుకోగలరు.", "పరీక్షకు ముందు, ప్రసంగం లేదా ఏదైనా కష్టమైన పని.", "ప్రవక్త మూసా (అ. స.) యొక్క దుఆ-హృదయ ప్రశాంతత మరియు ఒకరి పనిలో సౌలభ్యం."),
        "dua_la_tuzigh" to DuaText("హృదయ స్థిరత్వం", "మా ప్రభూ, నీవు మాకు మార్గనిర్దేశం చేసిన తర్వాత మా హృదయాలు మళ్ళిపోకండి, నీవంతు నీవు మాకు దయ చూపించు. నిశ్చయంగా నీవే మేలుచేసేవాడవు.", "మార్గదర్శకత్వం మీద స్థిరత్వం కోసం.", "విశ్వాసంలో దృఢంగా ఉండటానికి ఒక దుఆ."),
        "dua_ya_muqallib" to DuaText("ఓ టర్నర్ ఆఫ్ హార్ట్స్", "ఓ హృదయపూర్వక టర్నర్, నీ మతంపై నా హృదయాన్ని స్థిరంగా ఉంచుకోండి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం తరచుగా ఈ దుఆ చేసేవారు.", "ఉమ్ సలమా (ర) ప్రకారం, ప్రవక్త సల్లల్లాహు అలైహి వసల్లం చాలా తరచుగా చేసే దుఆ."),
        "dua_la_tuakhidhna" to DuaText("సూరహ్ అల్-బఖరా యొక్క చివరి శ్లోకాలు", "మా ప్రభూ, మేము మర్చిపోతే లేదా పొరపాటు చేస్తే మమ్మల్ని శిక్షించవద్దు. మా ప్రభూ! మా మీద మీరు మాకు ముందు ఉన్నవారిపై మీరు మోపిన భారాన్ని మాపై మోపవద్దు. మా ప్రభూ! మేము భరించలేని భారాన్ని మాపై మోపవద్దు. మమ్మల్ని క్షమించండి, మమ్మల్ని క్షమించండి, మమ్మల్ని కరుణించండి. నీవే మాకు రక్షకుడు, కాబట్టి అవిశ్వాసుల నుండి మాకు సహాయం చేయండి.", "నిద్రపోయే ముందు రాత్రి-సూరహ్ అల్-బఖారా యొక్క చివరి రెండు శ్లోకాలు.", "సూరహ్ అల్-బఖరా యొక్క చివరి రెండు శ్లోకాలను రాత్రివేళ పఠించే వారెవరైనా, అవి అతనికి సరిపోతాయి."),
        "dua_visiting_sick" to DuaText("రోగిని సందర్శించడం", "మిమ్మల్ని నయం చేయమని నేను శక్తివంతమైన, శక్తివంతమైన సింహాసనానికి ప్రభువైన అల్లాహ్ను అడుగుతున్నాను.", "రోగులను సందర్శించినప్పుడు ఏడు సార్లు.", "మరణ సమయం రాకపోతే, అల్లాహ్ అతన్ని నయం చేస్తాడు."),
        "dua_ruqyah_pain" to DuaText("శారీరక నొప్పికి", "నేను భావించే దాని నుండి, భయపడే దాని నుండి అల్లాహ్ మరియు అతని శక్తిని ఆశ్రయిస్తాను.", "బాధించే చోట మీ చేతిని ఉంచండి, మూడు సార్లు బిస్మిల్లా అని చెప్పండి, తరువాత ఈ దుఆ ఏడు సార్లు చెప్పండి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం దీనిని ఉస్మాన్ ఇబ్న్ అబిల్ -'అస్ (ర) కు నొప్పి కోసం నేర్పించారు."),
        "dua_ruqyah_nabawi" to DuaText("రోగులకు ప్రవచనాత్మక రుకియా", "మానవుల ప్రభువైన అల్లాహ్! హానిని తొలగించి, నయం చేయి, ఎందుకంటే నీవే నయం చేసేవాడు, నీ చికిత్స తప్ప చికిత్స లేదు-ఏ అనారోగ్యాన్ని వదిలిపెట్టని నివారణ.", "అనారోగ్యంతో ఉన్న వ్యక్తి మీద చేతిని వేస్తున్నప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం అనారోగ్యంతో ఉన్న తన కుటుంబ సభ్యులను సందర్శించినప్పుడు దీనిని పఠించారు."),
        "dua_kalimat_tammat" to DuaText("పరిపూర్ణమైన పదాలలో శరణార్థిగా వెతకడం", "అల్లాహ్ సృష్టించిన దాని యొక్క చెడు నుండి నేను పరిపూర్ణమైన మాటలలో ఆశ్రయం పొందుతాను.", "ఒక ప్రదేశంలో లేదా సాయంత్రం ఆగినప్పుడు.", "ఒక చోట నిలబడి ఇలా చెప్పేవాడు, అతను దానిని విడిచిపెట్టేంత వరకు అతనికి ఏ హాని చేయడు."),
        "dua_evil_eye" to DuaText("పిల్లలకు రక్షణ (చెడు కన్ను)", "ప్రతి దెయ్యం నుండి, ప్రతి విషపూరిత జీవి నుండి, ప్రతి హానికరమైన కన్ను నుండి అల్లాహ్ యొక్క పరిపూర్ణ పదాలలో నేను మీ ఇద్దరికీ రక్షణ కోరుతున్నాను.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం హసన్ మరియు హుస్సేన్ (ర) లపై దీనిని పఠించారు.", "పిల్లలను చెడు కన్ను మరియు హాని నుండి రక్షించడానికి సున్నహ్ దుఆ (ఒక బిడ్డకు'ఉధుకా'అని చెప్పండి)."),
        "dua_seeing_afflicted" to DuaText("విచారణలో ఉన్న వ్యక్తిని చూడటం", "మిమ్మల్ని పరీక్షించిన దాని నుండి నన్ను తప్పించిన, తన సృష్టిలో చాలా వరకు నాపై అనుగ్రహం చేసిన అల్లాహ్ కు అన్ని ప్రశంసలు ఉన్నాయి.", "విచారణలో ఉన్న వ్యక్తిని చూసినప్పుడు (మీరే నిశ్శబ్దంగా చెప్పుకోండి).", "ఆ విచారణ నుండి సురక్షితంగా ఉంచబడ్డారని చెప్పే వ్యక్తి."),
        "dua_istikhara" to DuaText("సలాత్ అల్-ఇస్తికారా", "ఓ అల్లాహ్, నేను నీ జ్ఞానం ద్వారా మంచిని వెతుకుతున్నాను, నేను నీ శక్తి ద్వారా సామర్థ్యాన్ని వెతుకుతున్నాను, మరియు నేను నీ గొప్ప అనుగ్రహం గురించి నిన్ను అడుగుతున్నాను. నీకు శక్తి ఉంది, నాకు ఏదీ లేదు. నీకు తెలుసు, నాకు తెలియదు, మరియు నీవు అదృశ్య విషయాల పరిజ్ఞానం గలవాడవు. ఓ అల్లాహ్, నీకు తెలిస్తే ఈ విషయం (గుర్తుకు తెచ్చుకో) నా మతానికి, నా జీవితానికి మరియు నా ముగింపుకు మంచిది, అప్పుడు నాకు దానిని తీర్పు ఇవ్వండి, నాకు సులభతరం చేయండి మరియు దానిలో నన్ను ఆశీర్వదించండి. మరియు నీకు తెలిస్తే ఈ విషయం నా మతానికి, నా జీవితానికి మరియు నా ముగింపుకు చెడు అయితే, దానిని నా నుండి తిప్పండి, దాని నుండి నన్ను దూరం చేయండి, మరియు అది ఎక్కడ ఉన్నా నాకు మంచిని తీర్పు ఇవ్వండి, అప్పుడు దానితో నన్ను సంతృప్తి పరచండి.", "రెండు రకాలు స్వచ్ఛంద ప్రార్థన తరువాత, అనుమతించదగిన విషయంలో ఉత్తమమైనదాన్ని వెతకడం.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం సహచరులకు ఖురాన్ యొక్క సూరాను నేర్పించినందున అన్ని విషయాలలో ఇస్తికారా నేర్పించారు."),
    )
}
